body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 16px 64px;
  line-height: 1.5;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--color-primary);
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 16px;
}

header {
  text-align: center;
  max-width: 640px;
  width: 100%;
  margin-bottom: 40px;
}

header h1 {
  font-size: clamp(1.75rem, 4vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--color-text);
  margin-bottom: 8px;
}

header p {
  font-size: 1rem;
  color: var(--color-text-secondary);
}

main {
  width: 100%;
  max-width: 640px;
}

form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Question card */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px 28px 24px;
  box-shadow: var(--shadow-card);
  transition: box-shadow var(--transition);
}

.form-field:focus-within {
  box-shadow: var(--shadow-card-hover);
}

.form-field.has-error {
  border-color: var(--color-error-border);
  background-color: var(--color-error-bg);
}

fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 6px;
  display: block;
  width: 100%;
}

.question-number {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  /* #0057b8 gives ≥6.3:1 on all card backgrounds (white, #f0faf4, #fdf3f2) */
  color: #0057b8;
  margin-bottom: 6px;
}

.help-text {
  font-size: 0.875rem;
  color: var(--color-help);
  margin-bottom: 16px;
  line-height: 1.4;
}

.error-message {
  font-size: 0.875rem;
  color: var(--color-error);
  margin-bottom: 12px;
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.error-message::before {
  content: "⚠";
  font-size: 0.875rem;
  flex-shrink: 0;
  line-height: 1.4;
}

/* Checkbox options */
.options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.option-label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 0.9375rem;
  color: var(--color-text);
  transition: border-color var(--transition), background-color var(--transition);
  user-select: none;
}

.option-label:hover {
  border-color: var(--color-primary);
  background-color: #f0f7ff;
}

.option-label:has(input:checked) {
  border-color: var(--color-check-accent);
  background-color: #e8f1fd;
}

/* Custom checkbox */
.option-label input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  min-width: 20px;
  border: 2px solid var(--color-border);
  border-radius: 5px;
  background: #fff;
  cursor: pointer;
  transition: border-color var(--transition), background-color var(--transition);
  position: relative;
  display: grid;
  place-content: center;
}

.option-label input[type="checkbox"]:checked {
  background-color: var(--color-check-accent);
  border-color: var(--color-check-accent);
}

.option-label input[type="checkbox"]::after {
  content: "";
  width: 5px;
  height: 9px;
  border: 2px solid transparent;
  border-right: 2.5px solid #fff;
  border-bottom: 2.5px solid #fff;
  transform: rotate(45deg) translate(-1px, -1px);
  opacity: 0;
  transition: opacity var(--transition);
}

.option-label input[type="checkbox"]:checked::after {
  opacity: 1;
}

.option-label input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* Submit section */
.form-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 12px;
  margin-top: 8px;
}

button[type="submit"] {
  background: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: -0.01em;
}

button[type="submit"]:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 14px rgba(0, 113, 227, 0.35);
}

button[type="submit"]:active {
  background: var(--color-primary-active);
  transform: scale(0.99);
  box-shadow: none;
}

button[type="submit"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* Result announcement */
#quiz-result {
  border-radius: var(--radius-md);
  padding: 20px 24px;
  font-size: 1rem;
  line-height: 1.5;
}

#quiz-result:not(:empty) {
  background: var(--color-success-bg);
  border: 1.5px solid var(--color-success-border);
  color: var(--color-success-text);
  font-weight: 500;
}

#quiz-result .result-score {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 6px;
  display: block;
}

/* Correct/incorrect per-question feedback */
.form-field.correct {
  border-color: var(--color-success-border);
  background-color: var(--color-success-bg);
}

.form-field.incorrect {
  border-color: var(--color-error-border);
  background-color: var(--color-error-bg);
}

.feedback-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8125rem;
  font-weight: 600;
  margin-top: 14px;
  padding: 4px 10px;
  border-radius: 20px;
}

.feedback-badge.correct {
  background: #d4edda;
  color: #155724;
}

.feedback-badge.incorrect {
  background: #f8d7da;
  color: #721c24;
}

/* Forced colors */
@media (forced-colors: active) {
  .option-label {
    border: 2px solid ButtonText;
  }
  .option-label:has(input:checked) {
    border-color: Highlight;
    forced-color-adjust: none;
    background: Highlight;
    color: HighlightText;
  }
  .option-label input[type="checkbox"] {
    forced-color-adjust: auto;
  }
  button[type="submit"] {
    forced-color-adjust: auto;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
  }
}

/* Reflow — 320 px */
@media (max-width: 400px) {
  .form-field {
    padding: 20px 16px;
  }
}
